import{_ as o,c as i,o as t,ae as a}from"./chunks/framework.BGWP4WZ_.js";const m=JSON.parse('{"title":"py-xiaozhi Documentation Index","description":"","frontmatter":{},"headers":[],"relativePath":"guide/00_Documentation_Index.md","filePath":"guide/00_Documentation_Index.md"}'),n={name:"guide/00_Documentation_Index.md"};function r(l,e,c,s,u,d){return t(),i("div",null,e[0]||(e[0]=[a('<h1 id="py-xiaozhi-documentation-index" tabindex="-1">py-xiaozhi Documentation Index <a class="header-anchor" href="#py-xiaozhi-documentation-index" aria-label="Permalink to &quot;py-xiaozhi Documentation Index&quot;">​</a></h1><p>This directory contains all the documentation for the py-xiaozhi project, organized by functional modules for easy reference and use.</p><p>The project has the following modules enabled by default: Music, Lighting, Volume, Timer, Home Assistant Controller, and Camera IoT Control. Additional modules can be enabled and extended as needed.<br> The Visual Recognition feature requires configuring the API Key for the Zhipu AI model to function.<br> The project has adopted the v2 authorization protocol, with the WSS link returned via the OTA interface. Both the official Xiaozhi and open-source backends have aligned their authentication processes.</p><h2 id="basic-documentation" tabindex="-1">Basic Documentation <a class="header-anchor" href="#basic-documentation" aria-label="Permalink to &quot;Basic Documentation&quot;">​</a></h2><ul><li><a href="./01_System_Dependency_Installation.html">01_System Dependency Installation</a> - System dependencies and Python environment setup for various platforms.</li><li><a href="./02_Configuration_Guide.html">02_Configuration Guide</a> - Configuration file structure, explanation of configuration options, and modification guide.</li><li><a href="./03_Voice_Interaction_Mode_Guide.html">03_Voice Interaction Mode Guide</a> - Project overview, basic usage instructions, and operation modes.</li><li><a href="./04_Voice_Wakeup.html">04_Voice Wakeup</a> - Configuration and usage instructions for the voice wakeup feature.</li><li><a href="./05_IoT_Functionality_Guide.html">05_IoT Functionality Guide</a> - IoT functionality architecture, device control, and extension methods.</li><li><a href="./06_Volume_Control_Functionality.html">06_Volume Control Functionality</a> - Usage and configuration of the system volume control feature.</li><li><a href="./07_Visual_Recognition_Functionality.html">07_Visual Recognition Functionality</a> - Camera control and visual analysis functionality.</li><li><a href="./08_Device_Activation_Process.html">08_Device Activation Process</a> - Explanation of the device activation and registration process.</li><li><a href="./09_Packaging_Tutorial.html">09_Packaging Tutorial</a> - Detailed tutorial on packaging the Xiaozhi client using UnifyPy.</li><li><a href="./TTS_Functionality_Guide.html">TTS Functionality Guide</a> - Text-to-Speech functionality guide.</li></ul><h2 id="additional-documentation" tabindex="-1">Additional Documentation <a class="header-anchor" href="#additional-documentation" aria-label="Permalink to &quot;Additional Documentation&quot;">​</a></h2><ul><li><a href="./Error_Summary.html">Error Summary</a> - Common issues and their solutions.</li></ul><h2 id="legacy-documentation" tabindex="-1">Legacy Documentation <a class="header-anchor" href="#legacy-documentation" aria-label="Permalink to &quot;Legacy Documentation&quot;">​</a></h2><p>For reference purposes, we have retained the legacy documentation:</p><ul><li><a href="./old_docs/User_Guide.html">Legacy User Guide</a> - Usage instructions for earlier versions.</li></ul><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>If you wish to contribute to the project or provide feedback, please refer to the following resources:</p><ul><li><a href="/py-xiaozhi/contributing.html">Contribution Guide</a> - How to contribute to the project, including development processes, coding standards, and PR submission guidelines.</li><li><a href="/py-xiaozhi/about/team.html">Team Members</a> - Acknowledgment of team members who contributed to the project.</li><li><a href="/py-xiaozhi/sponsors/">Sponsorship Support</a> - How to sponsor the project&#39;s development.</li></ul><h2 id="related-ecosystem" tabindex="-1">Related Ecosystem <a class="header-anchor" href="#related-ecosystem" aria-label="Permalink to &quot;Related Ecosystem&quot;">​</a></h2><ul><li><a href="/py-xiaozhi/ecosystem/">Related Ecosystem</a> - Related ecosystems and extension projects for the py-xiaozhi project.</li></ul><h2 id="version-information" tabindex="-1">Version Information <a class="header-anchor" href="#version-information" aria-label="Permalink to &quot;Version Information&quot;">​</a></h2><p>Last updated: May 2025</p>',17)]))}const f=o(n,[["render",r]]);export{m as __pageData,f as default};
